"""Eigen ticket-RPC's in een geïsoleerde database; geen productie of betaalprovider."""
from concurrent.futures import ThreadPoolExecutor
import json,os,subprocess,unittest,uuid
from pathlib import Path
@unittest.skipUnless(os.environ.get('ASSISTENT_TEST_POSTGRES_CONTAINER'),'Eigen PostgreSQL-container vereist')
class StudioTicketsTests(unittest.TestCase):
 @classmethod
 def sql(cls,tekst,db=None):
  env={k:v for k,v in os.environ.items() if k not in {'DOCKER_HOST','DOCKER_CONTEXT','DOCKER_TLS','DOCKER_TLS_VERIFY','DOCKER_CERT_PATH'}}
  r=subprocess.run(['docker','--host=unix:///var/run/docker.sock','exec','-i',os.environ['ASSISTENT_TEST_POSTGRES_CONTAINER'],'psql','-U','postgres','-d',db or cls.db,'-XqAt','-v','ON_ERROR_STOP=1'],input=tekst,text=True,capture_output=True,env=env,timeout=30)
  if r.returncode:raise AssertionError(r.stderr)
  return r.stdout.strip()
 @classmethod
 def setUpClass(cls):
  cls.db='studio_'+uuid.uuid4().hex;cls.sql(f'create database "{cls.db}"','postgres');cls.addClassCleanup(lambda:cls.sql(f'drop database "{cls.db}" with(force)','postgres'))
  cls.sql("""do $$begin if not exists(select from pg_roles where rolname='anon')then create role anon;end if;if not exists(select from pg_roles where rolname='authenticated')then create role authenticated;end if;end$$;
   create schema private; create table private.gebruikers(id bigint primary key,naam text,weergavenaam text,geblokkeerd boolean default false,verwijderd boolean default false);
   create function private.gebruiker_id(text,text)returns bigint language sql as $$select id from private.gebruikers where naam=$1 and $2='test-only' and not geblokkeerd and not verwijderd$$;
   create table private.chat_communities(id bigint primary key,weg boolean default false);
   create table private.chat_community_leden(community bigint,gebruiker bigint,rol text);
   create function private.chat_community_rol(bigint,bigint)returns text language sql as $$select rol from private.chat_community_leden where gebruiker=$1 and community=$2$$;
   create function private.ca_beheer(bigint,bigint)returns boolean language sql as $$select coalesce(private.chat_community_rol($1,$2) in('eigenaar','beheerder'),false)$$;
   create table private.community_activiteiten(id bigint generated by default as identity primary key,community bigint,maker bigint,soort text default 'evenement',titel text,start timestamptz,einde timestamptz,plaats text,afgelast boolean default false,weg boolean default false,max_deelnemers int);
   create function public.community_activiteit_bewaren(text,text,bigint,bigint,jsonb,integer)returns jsonb language plpgsql as $$declare n bigint;begin insert into private.community_activiteiten(community,maker,titel,start,einde,plaats)values($3,private.gebruiker_id($1,$2),$5->>'titel',($5->>'start')::timestamptz,($5->>'einde')::timestamptz,$5->>'plaats')returning id into n;return jsonb_build_object('ok',true,'ids',jsonb_build_array(n));end$$;""")
  cls.sql(Path('sql/studio_tickets.sql').read_text())
 def setUp(self):
  self.sql("""truncate private.event_ticketlog,private.event_tickets,private.event_scanners,private.event_ticketinstellingen,private.studio_event_opdrachten,private.community_activiteiten,private.chat_community_leden,private.chat_communities,private.gebruikers restart identity cascade;
   insert into private.gebruikers(id,naam)values(1,'host'),(2,'gast'),(3,'scan'),(4,'buiten'),(5,'beheer');insert into private.chat_communities values(1,false),(2,false);
   insert into private.chat_community_leden values(1,1,'eigenaar'),(1,2,'lid'),(1,3,'lid'),(1,5,'beheerder');
   insert into private.community_activiteiten(id,community,maker,titel,start,einde,plaats)values(10,1,1,'Testevent',now()-interval '1 hour',now()+interval '1 hour','Testzaal'),(11,1,1,'Ander event',now()-interval '1 hour',now()+interval '1 hour','Anders');""")
  self.configure()
 def call(self,fn,args):return json.loads(self.sql(f'select public.{fn}({args})'))
 def configure(self,capacity=10,version=0,who='host',everyone=False,opened=True,event=10):return self.call('event_tickets_instellen',f"'{who}','test-only',{event},{version},{str(opened).lower()},{str(everyone).lower()},{capacity}")
 def overview(self,who='host',event=10):return self.call('event_ticket_overzicht',f"'{who}','test-only',{event},''")
 def issue(self,who='gast',event=10,op=None):return self.call('event_ticket_maken',f"'{who}','test-only',{event},'{op or uuid.uuid4()}'")
 def code(self,who='gast',event=10):return self.overview(who,event)['mijn_ticket']['code']
 def scan(self,who='host',event=10,code=None,op=None,admit=False):return self.call('event_ticket_controleren',f"'{who}','test-only',{event},'{code or self.code()}','{op or uuid.uuid4()}',{str(admit).lower()}")
 def test_only_managers_can_configure_and_versions_and_capacity_are_checked(self):
  self.assertIn('fout',self.configure(who='gast',version=1));self.assertIn('fout',self.configure(version=0));self.issue();self.assertIn('fout',self.configure(capacity=0,version=1));self.assertTrue(self.configure(capacity=2,version=1)['ok'])
 def test_issue_is_idempotent_and_capacity_is_serialized(self):
  self.configure(capacity=1,version=1)
  with ThreadPoolExecutor(2) as pool:r=list(pool.map(self.issue,['gast','scan']))
  self.assertEqual(sum('id'in x for x in r),1);self.assertEqual(self.sql('select count(*) from private.event_tickets'),'1')
  who='gast'if'id'in r[0]else'scan';self.assertEqual(self.issue(who)['id'],r[0 if who=='gast'else 1]['id'])
 def test_visitors_cannot_read_other_codes_or_participants_or_scan(self):
  self.issue();r=self.overview('scan');self.assertIsNone(r['mijn_ticket']);self.assertEqual(r['bezoekers'],[]);self.assertNotIn(self.code(),json.dumps(r));self.assertIn('fout',self.scan(who='scan'))
 def test_open_registration_is_explicit_and_ticket_data_is_private(self):
  self.assertIn('fout',self.issue('buiten'));self.configure(version=1,everyone=True);self.assertIn('id',self.issue('buiten'));self.assertEqual(self.overview('buiten')['bezoekers'],[])
 def test_preview_does_not_admit_and_concurrent_scanners_only_admit_once(self):
  self.issue();self.assertEqual(self.scan()['status'],'geldig');self.assertEqual(self.overview()['binnen'],0)
  with ThreadPoolExecutor(2) as pool:r=list(pool.map(lambda _:self.scan(admit=True),range(2)))
  self.assertEqual(sorted(x['status'] for x in r),['al_binnen','toegelaten']);self.assertEqual(self.sql("select count(*) from private.event_ticketlog where actie='toegang'"),'1')
 def test_same_admission_request_can_retry_but_a_new_request_cannot(self):
  self.issue();op=uuid.uuid4();self.assertEqual(self.scan(op=op,admit=True)['status'],'toegelaten');self.assertTrue(self.scan(op=op,admit=True)['eerder']);self.assertEqual(self.scan(admit=True)['status'],'al_binnen')
 def test_wrong_event_cancelled_and_outside_time_window_never_admit(self):
  self.issue();code=self.code();self.configure(event=11);self.assertEqual(self.scan(event=11,code=code,admit=True)['status'],'ongeldig');self.sql('update private.community_activiteiten set afgelast=true where id=10');self.assertEqual(self.scan(code=code,admit=True)['status'],'niet_beschikbaar');self.sql("update private.community_activiteiten set afgelast=false,start=now()+interval '2 days',einde=now()+interval '3 days'where id=10");self.assertEqual(self.scan(code=code,admit=True)['status'],'niet_beschikbaar')
 def test_revoked_ticket_never_admits(self):
  ticket=self.issue()['id'];self.call('event_ticket_intrekken',f"'host','test-only',10,'{ticket}'");self.assertEqual(self.scan(admit=True)['status'],'ingetrokken')
 def test_scan_rights_can_be_delegated_and_revoked(self):
  self.issue();self.assertTrue(self.call('event_scanner_instellen',"'host','test-only',10,'scan',true")['ok']);self.assertEqual(self.scan(who='scan')['status'],'geldig');self.call('event_scanner_instellen',"'host','test-only',10,'scan',false");self.assertIn('fout',self.scan(who='scan'));self.assertIn('fout',self.call('event_scanner_instellen',"'gast','test-only',10,'scan',true"))
 def test_removed_group_members_lose_scan_rights(self):
  self.issue();self.call('event_scanner_instellen',"'host','test-only',10,'scan',true");self.sql('delete from private.chat_community_leden where gebruiker=3');self.assertIn('fout',self.scan(who='scan'))
 def test_private_tables_are_inaccessible_to_api_roles(self):
  for table in ['event_tickets','event_scanners','event_ticketlog','event_ticketinstellingen','studio_event_opdrachten']:
   self.assertEqual(self.sql(f"select has_table_privilege('anon','private.{table}','select')"),'f')
 def test_event_builder_retries_same_request_without_second_event(self):
  op=uuid.uuid4();g=json.dumps(dict(soort='evenement',event_type='workshop',titel='Workshop',start='2030-01-01T12:00:00Z',einde='2030-01-01T14:00:00Z',plaats='Zaal'))
  args=f"'host','test-only',1,'{op}','{g}'::jsonb";r=self.call('studio_evenement_maken',args);self.assertEqual(self.call('studio_evenement_maken',args)['id'],r['id']);self.assertIn('fout',self.call('studio_evenement_maken',args.replace('Workshop','Anders')))

 def test_null_admission_flag_never_admits(self):
  self.issue();r=self.call('event_ticket_controleren',f"'host','test-only',10,'{self.code()}','{uuid.uuid4()}',null");self.assertEqual(r['status'],'geldig');self.assertEqual(self.overview()['binnen'],0)
 def test_closed_group_stops_new_tickets_and_scanning(self):
  self.issue();self.sql('update private.chat_communities set weg=true where id=1');self.assertIn('fout',self.issue('scan'));self.assertIn('fout',self.scan(admit=True))
 def test_capacity_cannot_drop_below_issued_tickets(self):
  self.issue();self.issue('scan');self.assertIn('fout',self.configure(capacity=1,version=1));self.assertEqual(self.overview()['instellingen']['capaciteit'],10)
 def test_event_type_is_stored_and_invalid_type_is_rejected(self):
  op=uuid.uuid4();g=json.dumps(dict(soort='evenement',event_type='concert',titel='Concert',start='2030-01-01T12:00:00Z',einde='2030-01-01T14:00:00Z',plaats='Zaal'));args=f"'host','test-only',1,'{op}','{g}'::jsonb";r=self.call('studio_evenement_maken',args);self.assertEqual(self.overview(event=r['id'])['evenement']['event_type'],'concert');self.assertIn('fout',self.call('studio_evenement_maken',args.replace(str(op),str(uuid.uuid4())).replace('concert','onbekend')))

 def test_event_selector_is_authorized_and_returns_no_attendee_or_ticket_data(self):
  self.issue();r=self.call('studio_evenementen_lijst',"'host','test-only',1");self.assertEqual(len(r['evenementen']),2);self.assertNotIn(self.code(),json.dumps(r));self.assertNotIn('bezoekers',json.dumps(r));self.assertIn('fout',self.call('studio_evenementen_lijst',"'buiten','test-only',1"))
